import { fileURLToPath } from "node:url";
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";
import { isEntrypoint } from "./entrypoint.js";

/** Folder with the SQL migrations generated by drizzle-kit (works from both src/ and dist/). */
export const migrationsFolder = fileURLToPath(new URL("../drizzle", import.meta.url));

export async function runMigrations(databaseUrl: string): Promise<void> {
  const client = postgres(databaseUrl, { max: 1, onnotice: () => {} });
  try {
    await migrate(drizzle(client), { migrationsFolder });
  } finally {
    await client.end({ timeout: 5 });
  }
}

if (isEntrypoint(import.meta.url)) {
  const url = process.env.DATABASE_URL;
  if (!url) {
    console.error("[db:migrate] DATABASE_URL is not set (see packages/db/.env.example).");
    process.exit(1);
  }
  runMigrations(url)
    .then(() => console.log("[db:migrate] migrations applied"))
    .catch((error: unknown) => {
      console.error("[db:migrate] failed:", error);
      process.exit(1);
    });
}
